function stempleKnapp(){const b=el('button',{class:'button stemple',type:'button','data-stemple':'ja',text:'○  Stemple inn'});let inne=false;const vis=d=>{inne=!!d.innstemplet;b.textContent=inne?'●  Stemple ut':'○  Stemple inn';b.title=inne?(d.siden?'Verkstedet er åpent · siden '+d.siden:'Verkstedet er åpent'):'Verkstedet står som stengt';b.classList.toggle('primary',inne);};const kall=async body=>{const r=await fetch('/api/stempling.php',{credentials:'same-origin',cache:'no-store',...(body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{})});let d;try{d=await r.json();}catch{throw Error('Prøv igjen, eller si fra i verkstedet.');}if(!r.ok||!d||!d.timer)throw Error((d&&d.feil)||'Prøv igjen, eller si fra i verkstedet.');return d;};kall().then(vis).catch(()=>{});b.onclick=async()=>{b.disabled=true;try{const d=await kall({handling:inne?'ut':'inn'});vis(d);toast(d.innstemplet?'Du er stemplet inn. Timen teller fra '+d.siden+'.':'Du er stemplet ut. Du har brukt '+d.timer.brukt+' timer denne måneden.');}catch(e){toast('Fikk ikke registrert. '+e.message);}finally{b.disabled=false;}};return b;}
